{
  "mechanisms": [
    {
      "name": "independent_betas",
      "title": "Independent MB/MF Betas",
      "description": "Uses separate inverse temperature parameters to independently scale model-based and model-free values, replacing the traditional shared beta and mixing weight.",
      "params": [
        {
          "name": "beta_mb",
          "bounds": [0, 10]
        },
        {
          "name": "beta_mf",
          "bounds": [0, 10]
        }
      ],
      "evidence": "logits_stage1 = (beta_mb * q_mb_stage1) + (beta_mf * q_mf_stage1)\n...\nlogits_stage2 = beta_mf * q_mf_stage2[s_idx]",
      "expressible_in_slots": true
    },
    {
      "name": "choice_stickiness",
      "title": "Choice Stickiness",
      "description": "Adds a scalar bonus to the stage 1 logit of the action chosen on the previous trial to model perseveration.",
      "params": [
        {
          "name": "stickiness",
          "bounds": [0, 5]
        }
      ],
      "evidence": "if last_action_1 != -1:\n            logits_stage1[last_action_1] += stickiness",
      "expressible_in_slots": true
    },
    {
      "name": "direct_stage1_reward_update",
      "title": "Direct Stage 1 Reward Update",
      "description": "Updates the stage 1 model-free Q-value directly using the final reward, equivalent to an eligibility trace (lambda) of 1.",
      "params": [],
      "evidence": "q_mf_stage1[a1] += learning_rate * (r - q_mf_stage1[a1])",
      "expressible_in_slots": true
    }
  ]
}
